using System;
using System.Diagnostics;
using System.IO;
using System.Security.Principal;
using System.Xml;
using System.Windows.Forms;
namespace Basalt.Windows {
 static class StartupRegistration {
  static string Name {get{return "Basalt-"+WindowsIdentity.GetCurrent().User.Value;}}
  public static string TaskXml(string executable,string sid){var text=new System.Text.StringBuilder();using(var x=XmlWriter.Create(text,new XmlWriterSettings{Indent=true})){x.WriteStartDocument();x.WriteStartElement("Task","http://schemas.microsoft.com/windows/2004/02/mit/task");x.WriteAttributeString("version","1.2");x.WriteStartElement("Triggers");x.WriteStartElement("LogonTrigger");x.WriteElementString("Enabled","true");x.WriteElementString("UserId",sid);x.WriteEndElement();x.WriteEndElement();x.WriteStartElement("Principals");x.WriteStartElement("Principal");x.WriteAttributeString("id","User");x.WriteElementString("UserId",sid);x.WriteElementString("LogonType","InteractiveToken");x.WriteElementString("RunLevel","HighestAvailable");x.WriteEndElement();x.WriteEndElement();x.WriteStartElement("Settings");x.WriteElementString("MultipleInstancesPolicy","IgnoreNew");x.WriteElementString("DisallowStartIfOnBatteries","false");x.WriteElementString("StopIfGoingOnBatteries","false");x.WriteElementString("ExecutionTimeLimit","PT0S");x.WriteElementString("Enabled","true");x.WriteEndElement();x.WriteStartElement("Actions");x.WriteAttributeString("Context","User");x.WriteStartElement("Exec");x.WriteElementString("Command",executable);x.WriteElementString("Arguments","--startup");x.WriteElementString("WorkingDirectory",Path.GetDirectoryName(executable));x.WriteEndElement();x.WriteEndElement();x.WriteEndElement();}return text.ToString();}
  public static void Configure(bool enabled){if(Environment.OSVersion.Version.Major<6)throw new NotSupportedException("Automatic startup requires Windows Vista or later.");if(TunnelSession.IsAdministrator){Apply(enabled);return;}using(var p=Process.Start(new ProcessStartInfo(Application.ExecutablePath,enabled?"--startup-register":"--startup-remove"){UseShellExecute=true,Verb="runas"})){p.WaitForExit();if(p.ExitCode!=0)throw new IOException("Could not configure automatic startup.");}}
  public static void Apply(bool enabled){if(!TunnelSession.IsAdministrator)throw new UnauthorizedAccessException("Administrator required.");string xml=Path.Combine(Path.GetTempPath(),"Basalt-task-"+Guid.NewGuid().ToString("N")+".xml");try{if(enabled)File.WriteAllText(xml,TaskXml(Application.ExecutablePath,WindowsIdentity.GetCurrent().User.Value),System.Text.Encoding.Unicode);string args=enabled?"/Create /TN \""+Name+"\" /XML \""+xml+"\" /F":"/Delete /TN \""+Name+"\" /F";using(var p=Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"schtasks.exe"),args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){p.BeginOutputReadLine();p.BeginErrorReadLine();if(!p.WaitForExit(15000)){p.Kill();throw new IOException("Task Scheduler timed out.");}if(p.ExitCode!=0)throw new IOException("Task Scheduler could not update Basalt startup.");}}finally{if(File.Exists(xml))File.Delete(xml);}}
 }
}
